function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function resolveLink(link) {
  if (!link) return null;
  if (typeof link === 'string') return { url: link, target: '_self' };
  if (typeof link === 'object' && link.url) return { url: link.url, target: link.target || '_self' };
  return null;
}

const ICON_SVG = '<svg class="floating-button__icon" viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false"><path d="M3.5 8h9M8.5 3.5 13 8l-4.5 4.5" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

export default {
  async main(input = {}) {
    const {
      label = 'Label',
      link = null,
      ariaLabel = '',
      landmarkLabel = 'Floating action button',
    } = input;

    const actionClass = 'floating-button__action button';

    const ariaLabelAttr = ariaLabel && ariaLabel !== label ? ` aria-label="${esc(ariaLabel)}"` : '';

    const resolved = resolveLink(link);
    const content = `<span data-sq-field="label">${esc(label)}</span>${ICON_SVG}`;

    const actionHtml = resolved
      ? `<a class="${actionClass}" href="${esc(resolved.url)}"${resolved.target !== '_self' ? ` target="${esc(resolved.target)}" rel="noopener noreferrer"` : ''}${ariaLabelAttr}>${content}</a>`
      : `<button type="button" class="${actionClass}"${ariaLabelAttr}>${content}</button>`;

    return /*html*/`
<div class="floating-button" role="complementary" aria-label="${esc(landmarkLabel)}">
  <div class="floating-button__container">
    <div class="floating-button__button-wrapper">
      ${actionHtml}
    </div>
  </div>
</div>
`;
  },
};
