import { html } from 'lit';
import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import comp from './main.js';

const squiz = squizStoryRenderer(comp.main);

/**
 * The component is position:fixed, so it contributes no height to normal
 * document flow. Storybook's docs canvas auto-sizes each story by measuring
 * that flow height, so without this wrapper it renders as a near-0px box
 * and the fixed button gets clipped/scrolled instead of shown in full.
 */
function withPageContent(input) {
  return html`
    <div style="padding-block-end: 140px; min-height: 260px;">
      <div style="max-width: 800px; margin: 0 auto; padding: 24px;">
        <p>This preview simulates page content above the fixed button below, so the docs canvas has enough height to show it in full.</p>
      </div>
      ${squiz(input)}
    </div>
  `;
}

export default {
  title: 'dxp/Floating Button',
};

const defaultArgs = {
  label: 'Label',
};

const defaultHtml = await squiz.markup(defaultArgs);

export const Default = {
  render: (args) => withPageContent(args),
  args: defaultArgs,
  argTypes: {
    label: { control: 'text' },
    link: { control: 'text', description: 'Optional URL. When set, renders as a link instead of a plain button.' },
    ariaLabel: { control: 'text' },
    landmarkLabel: { control: 'text' },
  },
  parameters: {
    docs: {
      source: {
        code: defaultHtml,
        language: 'html',
        type: 'code',
      },
    },
  },
};
